def dec_stream(b):
    outs=[]
    for m in re.finditer(rb'(?s)stream\r?\n(.*?)\r?\nendstream',b):
        s=m.group(1)
        try: outs.append(zlib.decompress(s))
        except Exception: outs.append(s)
    return outs

def parse_cmap(st):
    mp={}; s=st.decode('latin1','ignore')
    for block in re.findall(r'beginbfchar(.*?)endbfchar',s,re.S):
        for a,b in re.findall(r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>',block):
            try: mp[a.upper()]=bytes.fromhex(b).decode('utf-16-be','ignore')
            except Exception: pass
    for block in re.findall(r'beginbfrange(.*?)endbfrange',s,re.S):
        consumed=[]
        for a,b,arr in re.findall(r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*\[(.*?)\]',block,re.S):
            consumed.append((a,b))
            vals=re.findall(r'<([0-9A-Fa-f]+)>',arr); start=int(a,16); width=len(a)
            for i,v in enumerate(vals):
                try: mp[format(start+i,'0{}X'.format(width))]=bytes.fromhex(v).decode('utf-16-be','ignore')
                except Exception: pass
        # remove array parts to avoid triple matching inside arrays
        block2=re.sub(r'<[0-9A-Fa-f]+>\s*<[0-9A-Fa-f]+>\s*\[.*?\]','',block,flags=re.S)
        for a,b,c in re.findall(r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>',block2):
            start,end,base=int(a,16),int(b,16),int(c,16); width=len(a)
            if end-start>1000: continue
            for code in range(start,end+1):
                val=base+code-start
                try: mp[format(code,'0{}X'.format(width))]=val.to_bytes(max(2,(val.bit_length()+7)//8),'big').decode('utf-16-be','ignore')
                except Exception: pass
    return mp

def decode_hex(h,cmap):
    h=re.sub(r'\s+','',h.upper()); out=[]; i=0
    lens=sorted({len(k) for k in cmap}, reverse=True)
    while i<len(h):
        for L in lens:
            k=h[i:i+L]
            if len(k)==L and k in cmap:
                out.append(cmap[k]); i+=L; break
        else:
            if i+2<=len(h):
                try:
                    b=int(h[i:i+2],16); out.append(chr(b) if 32<=b<127 else '')
                except Exception: pass
            i+=2
    return ''.join(out)

def extract(path):
    d=open(path,'rb').read()
    objs={int(n):body for n,body in re.findall(rb'(?s)(\d+)\s+0\s+obj(.*?)endobj',d)}
    fonts={m.group(1).decode():int(m.group(2)) for m in re.finditer(rb'/(F\d+)\s+(\d+)\s+0\s+R',d)}
    cmaps={}
    for fn,on in fonts.items():
        m=re.search(rb'/ToUnicode\s+(\d+)\s+0\s+R',objs.get(on,b''))
        if m:
            mp={}
            for st in dec_stream(objs.get(int(m.group(1)),b'')): mp.update(parse_cmap(st))
            cmaps[fn]=mp
    parts=[]
    tok=re.compile(r'/(F\d+)\s+[0-9.]+\s+Tf|/ActualText\s*<FEFF([0-9A-Fa-f]+)>|<([0-9A-Fa-f\s]+)>\s*Tj|\[(.*?)\]\s*TJ|(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)\s+Td|ET',re.S)
    for st in dec_stream(d):
