49	     *
50	     * @param userPrompt 用户提示词
51	     * @return 执行结果
52	     */
53	    public String run(String userPrompt) {
54	        // 1、基础校验
55	        if (this.state != AgentState.IDLE) {
56	            throw new RuntimeException("Cannot run agent from state: " + this.state);
57	        }
58	        if (StrUtil.isBlank(userPrompt)) {
59	            throw new RuntimeException("Cannot run agent with empty user prompt");
60	        }
61	        // 2、执行，更改状态
62	        this.state = AgentState.RUNNING;
63	        // 记录消息上下文
64	        messageList.add(new UserMessage(userPrompt));
65	        // 保存结果列表
66	        List<String> results = new ArrayList<>();
67	        try {
68	            // 执行循环
69	            for (int i = 0; i < maxSteps && state != AgentState.FINISHED; i++) {
70	                int stepNumber = i + 1;
71	                currentStep = stepNumber;
72	                log.info("Executing step {}/{}", stepNumber, maxSteps);
73	                // 单步执行
74	                String stepResult = step();
75	                String result = "Step " + stepNumber + ": " + stepResult;
76	                results.add(result);
77	            }
78	            // 检查是否超出步骤限制
79	            if (currentStep >= maxSteps) {
80	                state = AgentState.FINISHED;
81	                results.add("Terminated: Reached max steps (" + maxSteps + ")");
82	            }
83	            return String.join("\n", results);
84	        } catch (Exception e) {
85	            state = AgentState.ERROR;
86	            log.error("error executing agent", e);
87	            return "执行错误" + e.getMessage();
88	        } finally {
89	            // 3、清理资源
90	            this.cleanup();
91	        }
