2	
3	import cn.hutool.core.collection.CollUtil;
4	import cn.hutool.core.util.StrUtil;
5	import com.alibaba.cloud.ai.dashscope.chat.DashScopeChatOptions;
6	import com.flora.floraaiagent.agent.model.AgentState;
7	import lombok.Data;
8	import lombok.EqualsAndHashCode;
9	import lombok.extern.slf4j.Slf4j;
10	import org.springframework.ai.chat.messages.AssistantMessage;
11	import org.springframework.ai.chat.messages.Message;
12	import org.springframework.ai.chat.messages.ToolResponseMessage;
13	import org.springframework.ai.chat.messages.UserMessage;
14	import org.springframework.ai.chat.model.ChatResponse;
15	import org.springframework.ai.chat.prompt.ChatOptions;
16	import org.springframework.ai.chat.prompt.Prompt;
17	import org.springframework.ai.model.tool.ToolCallingManager;
18	import org.springframework.ai.model.tool.ToolExecutionResult;
19	import org.springframework.ai.tool.ToolCallback;
20	
21	import java.util.List;
22	import java.util.stream.Collectors;
23	
24	/**
25	 * 处理工具调用的基础代理类，具体实现了 think 和 act 方法，可以用作创建实例的父类
26	 */
27	@EqualsAndHashCode(callSuper = true)
28	@Data
29	@Slf4j
30	public class ToolCallAgent extends ReActAgent {
31	
32	    // 可用的工具
33	    private final ToolCallback[] availableTools;
34	
35	    // 保存工具调用信息的响应结果（要调用那些工具）
36	    private ChatResponse toolCallChatResponse;
37	
38	    // 工具调用管理者
39	    private final ToolCallingManager toolCallingManager;
40	
41	    // 禁用 Spring AI 内置的工具调用机制，自己维护选项和消息上下文
42	    private final ChatOptions chatOptions;
43	
44	    public ToolCallAgent(ToolCallback[] availableTools) {
45	        super();
46	        this.availableTools = availableTools;
47	        this.toolCallingManager = ToolCallingManager.builder().build();
48	        // 禁用 Spring AI 内置的工具调用机制，自己维护选项和消息上下文
49	        this.chatOptions = DashScopeChatOptions.builder()
50	                .withInternalToolExecutionEnabled(false)
51	                .build();
52	    }
53	
54	    /**
55	     * 处理当前状态并决定下一步行动
56	     *
57	     * @return 是否需要执行行动
58	     */
59	    @Override
60	    public boolean think() {
61	        // 1、校验提示词，拼接用户提示词
62	        if (StrUtil.isNotBlank(getNextStepPrompt())) {
63	            UserMessage userMessage = new UserMessage(getNextStepPrompt());
64	            getMessageList().add(userMessage);
65	        }
66	        // 2、调用 AI 大模型，获取工具调用结果
67	        List<Message> messageList = getMessageList();
68	        Prompt prompt = new Prompt(messageList, this.chatOptions);
69	        try {
70	            ChatResponse chatResponse = getChatClient().prompt(prompt)
71	                    .system(getSystemPrompt())
72	                    .tools(availableTools)
73	                    .call()
74	                    .chatResponse();
75	            // 记录响应，用于等下 Act
76	            this.toolCallChatResponse = chatResponse;
77	            // 3、解析工具调用结果，获取要调用的工具
78	            // 助手消息
79	            AssistantMessage assistantMessage = chatResponse.getResult().getOutput();
80	            // 获取要调用的工具列表
81	            List<AssistantMessage.ToolCall> toolCallList = assistantMessage.getToolCalls();
82	            // 输出提示信息
83	            String result = assistantMessage.getText();
84	            log.info(getName() + "的思考：" + result);
85	            log.info(getName() + "选择了 " + toolCallList.size() + " 个工具来使用");
86	            String toolCallInfo = toolCallList.stream()
87	                    .map(toolCall -> String.format("工具名称：%s，参数：%s", toolCall.name(), toolCall.arguments()))
88	                    .collect(Collectors.joining("\n"));
89	            log.info(toolCallInfo);
90	            // 如果不需要调用工具，返回 false
91	            if (toolCallList.isEmpty()) {
92	                // 只有不调用工具时，才需要手动记录助手消息
93	                getMessageList().add(assistantMessage);
94	                return false;
95	            } else {
96	                // 需要调用工具时，无需记录助手消息，因为调用工具时会自动记录
97	                return true;
98	            }
99	        } catch (Exception e) {
100	            log.error(getName() + "的思考过程遇到了问题：" + e.getMessage());
101	            getMessageList().add(new AssistantMessage("处理时遇到了错误：" + e.getMessage()));
102	            return false;
103	        }
104	    }
105	
106	    /**
107	     * 执行工具调用并处理结果
108	     *
109	     * @return 执行结果
110	     */
111	    @Override
112	    public String act() {
113	        if (!toolCallChatResponse.hasToolCalls()) {
114	            return "没有工具需要调用";
115	        }
116	        // 调用工具
117	        Prompt prompt = new Prompt(getMessageList(), this.chatOptions);
118	        ToolExecutionResult toolExecutionResult = toolCallingManager.executeToolCalls(prompt, toolCallChatResponse);
119	        // 记录消息上下文，conversationHistory 已经包含了助手消息和工具调用返回的结果
120	        setMessageList(toolExecutionResult.conversationHistory());
121	        ToolResponseMessage toolResponseMessage = (ToolResponseMessage) CollUtil.getLast(toolExecutionResult.conversationHistory());
122	        // 判断是否调用了终止工具
123	        boolean terminateToolCalled = toolResponseMessage.getResponses().stream()
124	                .anyMatch(response -> response.name().equals("doTerminate"));
125	        if (terminateToolCalled) {
126	            // 任务结束，更改状态
127	            setState(AgentState.FINISHED);
128	        }
129	        String results = toolResponseMessage.getResponses().stream()
130	                .map(response -> "工具 " + response.name() + " 返回的结果：" + response.responseData())
131	                .collect(Collectors.joining("\n"));
132	        log.info(results);
133	        return results;
134	    }
135	}
